// Classify a Telegram update into one route for the Switch node.
// kinds: file | review | fix_prompt | correction | question | help | ignore
const body = $input.first().json.body || {};
const msg = body.message;
const cq = body.callback_query;
const out = { kind: 'ignore', update_id: body.update_id };

const who = (u) => (u && (u.username || [u.first_name, u.last_name].filter(Boolean).join(' ') || String(u.id))) || null;
const COMMANDS = {
  '/deadlines': 'Which payments and document expiry dates fall within the next 30 days? And are there overdue payments from the last 30 days?',
};

if (cq) {
  const [action, id] = String(cq.data || '').split(':');
  Object.assign(out, {
    chat_id: cq.message.chat.id,
    message_id: cq.message.message_id,
    callback_id: cq.id,
    doc_id: Number(id),
    action,
    reviewer: who(cq.from),
  });
  if (action === 'fix') out.kind = 'fix_prompt';
  else if (action === 'approve' || action === 'reject') out.kind = 'review';
} else if (msg) {
  Object.assign(out, { chat_id: msg.chat.id, message_id: msg.message_id, reviewer: who(msg.from) });
  const text = (msg.text || '').trim();
  const command = text.startsWith('/') ? text.split(/[\s@]/)[0].toLowerCase() : null;
  const replied = msg.reply_to_message && msg.reply_to_message.text;
  const ref = replied && replied.match(/#(\d+)/);
  if (msg.document) {
    Object.assign(out, { kind: 'file', file_id: msg.document.file_id, file_name: msg.document.file_name || null });
  } else if (msg.photo && msg.photo.length) {
    // Telegram sends several sizes; the last one is the largest
    Object.assign(out, { kind: 'file', file_id: msg.photo[msg.photo.length - 1].file_id, file_name: null });
  } else if (ref && text.includes('=')) {
    // reply to "✏️ Correcting document #12" with lines "field=value"
    const fields = {};
    for (const line of text.split('\n')) {
      const m = line.match(/^\s*([a-z_]+)\s*=\s*(.*?)\s*$/);
      if (m) fields[m[1]] = m[2] === '' || m[2].toLowerCase() === 'null' ? null : m[2];
    }
    Object.assign(out, { kind: 'correction', doc_id: Number(ref[1]), action: 'correct', fields });
  } else if (command && COMMANDS[command]) {
    Object.assign(out, { kind: 'question', question: COMMANDS[command] });
  } else if (text && !command) {
    Object.assign(out, { kind: 'question', question: text.slice(0, 1000) });
  } else {
    out.kind = 'help';   // /start, /help, stickers, voice, ...
  }
}
return [{ json: out }];

// Shared helpers, prepended to the Code nodes that format Telegram messages.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const TYPE = {
  invoice: 'Invoice', contract: 'Contract', insurance: 'Insurance policy',
  receipt: 'Receipt', utility_bill: 'Utility bill', other: 'Other document',
};
const money = (v, cur) => (v == null ? null : `${Number(v).toFixed(2)} ${cur || ''}`.trim());

function summary(d) {
  const f = d.fields || {};
  const rows = [
    ['Type', TYPE[f.doc_type] || f.doc_type],
    ['From', f.counterparty],
    ['To', f.recipient],
    ['Number', f.document_number],
    ['Date', f.issue_date],
    ['Amount', money(f.total_amount, f.currency)],
    ['Pay by', f.due_date],
    ['Valid', f.valid_from || f.valid_until ? `${f.valid_from || '?'} — ${f.valid_until || '?'}` : null],
  ];
  return rows.filter(([, v]) => v != null && v !== '').map(([k, v]) => `${k}: <b>${esc(v)}</b>`).join('\n');
}

const send = (chat_id, text, extra = {}) => ({ json: { method: 'sendMessage', payload: { chat_id, text, parse_mode: 'HTML', ...extra } } });
const answer = (callback_query_id, text) => ({ json: { method: 'answerCallbackQuery', payload: { callback_query_id, text } } });
const reviewKeyboard = (id, canApprove = true) => ({
  inline_keyboard: [[
    ...(canApprove ? [{ text: '✅ Approve', callback_data: `approve:${id}` }] : []),
    { text: '✏️ Correct', callback_data: `fix:${id}` },
    { text: '🗑 Reject', callback_data: `reject:${id}` },
  ]],
});
const apiError = (r) => {
  const detail = r.body && typeof r.body === 'object' ? r.body.detail ?? JSON.stringify(r.body) : r.body;
  return `${r.statusCode || r.error?.message || 'error'}: ${esc(typeof detail === 'string' ? detail : JSON.stringify(detail))}`;
};

// Chat not in TELEGRAM_ALLOWED_CHAT_IDS: tell the user their chat id so the owner can allow it.
const u = $('Parse update').first().json;
if (!u.chat_id) return [];
const out = [];
if (u.callback_id) out.push(answer(u.callback_id, 'No access'));
out.push(send(u.chat_id, `⛔ This chat has no access to DocFlow.\nChat ID: <code>${esc(u.chat_id)}</code>. Ask the administrator to add it to TELEGRAM_ALLOWED_CHAT_IDS.`));
return out;

